import{_ as e,o as t,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const c=JSON.parse('{"title":"大卫·马克斯韦尔","description":"","frontmatter":{"title":"大卫·马克斯韦尔","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/大卫·马克斯韦尔.md","filePath":"04_people/大卫·马克斯韦尔.md"}'),o={name:"04_people/大卫·马克斯韦尔.md"};function i(n,a,s,_,h,p){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="大卫·马克斯韦尔" tabindex="-1">大卫·马克斯韦尔 <a class="header-anchor" href="#大卫·马克斯韦尔" aria-label="Permalink to &quot;大卫·马克斯韦尔&quot;">​</a></h1><ul><li><strong>角色职位</strong>：房利美（Fannie Mae）CEO</li><li><strong>与巴菲特关系</strong>：推动房利美扩张的领导者，伯克希尔曾持有房利美股票</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>大卫·马克斯韦尔是房利美（Fannie Mae）的掌舵人，在他的任期内，房利美经历了大规模的扩张，业务版图和影响力显著提升。房利美作为美国最大的房屋抵押贷款融资机构，在美国房地产市场中扮演着举足轻重的角色。</p><p>马克斯韦尔领导下的房利美大力拓展了其核心业务——购买和担保抵押贷款，从而为银行体系释放出更多的贷款资金。这一模式极大地促进了美国住宅市场的流动性，也让房利美成为华尔街最受关注的金融机构之一。马克斯韦尔以战略眼光和强大的执行力推动了房利美的快速成长。</p><p>巴菲特曾投资房利美，看重的是其在住房金融领域不可替代的垄断地位和稳定的盈利模式。伯克希尔持有房利美股票，正是基于对其商业模式的长期看好。然而，房利美在2008年金融危机中遭遇重大危机，最终被美国政府接管，伯克希尔的投资也遭受了损失。这段投资经历后来成为巴菲特反思风险控制的重要案例，也提醒投资者，即使是看似稳固的政府支持企业，也隐藏着难以预见的尾部风险。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1980年代</strong>：担任房利美CEO，开启大规模业务扩张</li><li><strong>1990年代</strong>：领导房利美增长为美国最大抵押贷款融资机构</li><li><strong>2008年</strong>：房利美因次贷危机被政府接管，马克斯韦尔时代正式落幕</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=大卫·马克斯韦尔在1991年股东信中的原话">1991年：完整翻译|/01_letters/1991年/翻译</a></li></ul>',11)])])}const u=e(o,[["render",i]]);export{c as __pageData,u as default};
